import random
from eywa.state import MachineRuntime
from eywa.expr import ExprCompiler
from eywa.model import TypeSystem
B={'name':'B','kind':'bool'}
types=TypeSystem([B]); comp=ExprCompiler(types)
def brute(n,initial,trans,target):
 best=None;adj={i:[] for i in range(n)}
 for t in trans: adj[t[0]].append((t[1],t[2],t[3]))
 def dfs(u,seen,c,h,seq):
  nonlocal best
