   if v in seen:continue
   seen.add(v);seq.append(cmd);dfs(v,seen,c+co,h+1,seq);seq.pop();seen.remove(v)
 dfs(initial,{initial},0,0,[])
 return None if best is None else (best[1],best[0][0])
